document.addEventListener('DOMContentLoaded',()=>{Object.defineProperty(HTMLMediaElement.prototype,'playing',{get:function(){return!!(this.currentTime>0&&!this.paused&&!this.ended&&this.readyState>2)}});const e=()=>{const e=document.querySelectorAll('.backgroundvideo');e.length>=1&&e.forEach(function(e){e.playing||e.play()})},t=document.querySelector('body');t.addEventListener('click',e),t.addEventListener('touchstart',e)});
